#!/usr/bin/env bash
# Generate app/src/shared/protocol.ts from the engine's Pydantic protocol models (design item 46).
# Run it with `npm run gen-types` from app/. CI fails if the generated file is out of date.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
uv run --project "$root/engine" python -c "import json; from tearsheet.protocol import schema; print(json.dumps(schema()))" > "$tmp/schema.json"
version="$(uv run --project "$root/engine" python -c "from tearsheet import PROTOCOL_VERSION; print(PROTOCOL_VERSION)")"
"$root/app/node_modules/.bin/json2ts" -i "$tmp/schema.json" -o "$tmp/protocol.ts" --unreachableDefinitions \
  --bannerComment "/* Generated by scripts/gen-types.sh from engine/src/tearsheet/protocol.py. Don't edit by hand. */"
{
  cat "$tmp/protocol.ts"
  printf '\nexport const PROTOCOL_VERSION = %s\n' "$version"
} > "$root/app/src/shared/protocol.ts"
echo "Wrote app/src/shared/protocol.ts (protocol version $version)."
